// Description of the JSON returned by
// GET https://pokeapi.co/api/v2/pokemon?limit=650
//
// Used as the <PokeResponse> type on AxiosAdapter.get in SeedService.
// An interface is a compile-time hint. Unlike CreatePokemonDto, it has
// no class-validator rules, so a changed API response is not rejected here.

// Generated by https://quicktype.io
export interface PokeResponse {
    count:    number;   // total Pokemon available, not just this page
    next:     string;   // URL of the following page
    previous: null;     // this request starts at the first page, so there is no previous URL
    results:  Result[]; // one entry per Pokemon on this page
}

export interface Result {
    name: string;
    url:  string; // detail URL; SeedService reads the Pokedex number from it
}
